package main

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"
)

const (
	goHeader = `// SPDX-License-Identifier: Apache-2.0
// Copyright 2026 Cognitio S.r.l.

// Code generated by internal/compiler/constraint/factgen from the fact
// registry. DO NOT EDIT.
// Regenerate with ` + "`go generate ./internal/compiler/constraint/factgen`" + ` from
// the aggrega-cli checkout.

package constraint
`

	typesImportPath = "github.com/aggrega-ai/aggrega-cli/pkg/types"

	// viewContract is the contract every generated view carries, stated once
	// on the chain's base so a reader reaching any view reaches it.
	viewContract = `View is the base every stage's view embeds. It declares no fact of its own; it carries the contract every view shares.

A view exposes named facts and never a raw document. There is no accessor returning an authoring document, a graph, or a pointer to an authored entity type. That single property is what makes re-derivation impossible: a check handed no raw structure has nothing to derive from, so its declaration describes what it reads exhaustively rather than approximately.

A check may compose declared facts; it may not reach behind them. Composition is reading one accessor and filtering its result through another — a check wanting the populated sockets iterates the declared-name accessor and filters through the population predicate. That is the only thing a check can do, and it is legitimate and unavoidable; nothing here forbids it. What is closed is re-derivation: reaching behind an accessor to the underlying document to compute a fact the accessor does not name.

Accessors take arguments rather than being bound to a subject, because facts are keyed by tuples — per node and socket, per node and slot, per attachment and pillar and leaf — and an argument-taking accessor states its key in its signature.

One fact, one accessor, with no convenience variants. A fact exposed both as a predicate and as a set-returning form would be two code paths for one question. An accessor may return a composite record where the fact itself is composite; that is one fact, not several.

Host powers — the filesystem, the plugin cache, workspace configuration — are never facts and never appear here. They are declared on a separate axis, so a view cannot be the route to one. A power is declared on the stage whose own fact production exercises it, and every stage states its value, including a stage that reaches for nothing. A check declares none: it receives its view and its subject and nothing else, so every value it reads was already produced for it.`
)

// emitViews renders the view chain: one interface per stage, nesting by
// embedding, plus the composite records composite facts return.
func emitViews(c chain) ([]byte, error) {
	var b strings.Builder
	b.WriteString(goHeader)

	needsTypes := false
	for _, f := range facts {
		if strings.Contains(f.Returns, "types.") {
			needsTypes = true
		}
		for _, p := range f.Params {
			if strings.Contains(p.Type, "types.") {
				needsTypes = true
			}
		}
	}
	if needsTypes {
		fmt.Fprintf(&b, "\nimport %q\n", typesImportPath)
	}

	for _, r := range records {
		b.WriteString("\n")
		b.WriteString(wrapComment("", r.Doc))
		fmt.Fprintf(&b, "type %s struct {\n", r.Name)
		for i, f := range r.Fields {
			if i > 0 {
				b.WriteString("\n")
			}
			b.WriteString(wrapComment("\t", f.Doc))
			fmt.Fprintf(&b, "\t%s %s\n", f.Name, f.Type)
		}
		b.WriteString("}\n")
	}

	b.WriteString("\n")
	b.WriteString(wrapComment("", viewContract))
	b.WriteString("type View interface{}\n")

	for i, s := range c.order {
		embed := "View"
		if i > 0 {
			embed = viewName(c.order[i-1].Name)
		}
		doc := fmt.Sprintf("%s exposes the facts complete at the %s stage: %s.\n\nIt embeds %s, so every fact complete earlier is readable here and the containment is a compile-time fact rather than a documented convention. A check declaring this view is placed at this stage, because it is the earliest one at which every fact the check reads is complete.",
			viewName(s.Name), s.Name, s.Holds, embed)
		b.WriteString("\n")
		b.WriteString(wrapComment("", doc))
		fmt.Fprintf(&b, "type %s interface {\n", viewName(s.Name))
		fmt.Fprintf(&b, "\t%s\n", embed)
		for _, f := range c.facts[s.Name] {
			b.WriteString("\n")
			b.WriteString(wrapComment("\t", accessorDoc(f)))
			fmt.Fprintf(&b, "\t%s(%s) %s\n", accessorName(f.Name), paramList(f.Params), f.Returns)
		}
		b.WriteString("}\n")
	}

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("the generated view chain is not valid Go: %w", err)
	}
	return out, nil
}

// accessorDoc assembles one accessor's godoc: the fact's own documentation, then
// the two lines a reader needs to relate the accessor to the registry — what it
// is keyed by and which carrier it reads — and, where one exists, the reported
// exception to the no-raw-document rule.
func accessorDoc(f factDecl) string {
	doc := f.Doc
	doc += fmt.Sprintf("\n\nKeyed by %s; read from %s.",
		kind{Coordinates: f.Subject}.Display(), f.SourceField)
	if f.ReportedException != "" {
		doc += "\n\nReported exception: " + f.ReportedException + "."
	}
	return doc
}

func paramList(params []paramDecl) string {
	parts := make([]string, 0, len(params))
	for _, p := range params {
		parts = append(parts, p.Name+" "+p.Type)
	}
	return strings.Join(parts, ", ")
}

// emitSubjectKinds renders the derived subject-kind set.
func emitSubjectKinds(kinds []kind) ([]byte, error) {
	var b strings.Builder
	b.WriteString(goHeader)

	b.WriteString("\n")
	b.WriteString(wrapComment("", `SubjectKind names what a check is invoked once per.

The set is derived and not chosen: a kind exists if and only if some declared fact is keyed by it. So a kind appears here when the first fact keyed by it is declared, and disappears when the last one is removed — which makes the set a consequence of the facts rather than a list to keep in step with them.

A kind's coordinates are ordered outermost first, so a check declaring a kind is invoked once per innermost coordinate within each outer one.`))
	b.WriteString("type SubjectKind string\n")

	b.WriteString("\n")
	b.WriteString(wrapComment("", `TraversalModel names how the framework reaches instances of a subject kind.

It is derived from the kind's outermost coordinate rather than declared per kind. A kind rooted at a document is reached by the push model, because documents are read one at a time and the catalog is read lazily, so no point in the compilation holds a materialised document set to walk; the caller holding a document presents it. Every other kind is reached by walking a collection that does exist.`))
	b.WriteString("type TraversalModel string\n")

	b.WriteString("\n")
	b.WriteString("const (\n")
	b.WriteString("\t// TraversalPush is the model for a kind the framework cannot enumerate: the caller presents one instance as it arrives.\n")
	b.WriteString("\tTraversalPush TraversalModel = \"push\"\n\n")
	b.WriteString("\t// TraversalPull is the model for a kind the framework enumerates by walking a collection.\n")
	b.WriteString("\tTraversalPull TraversalModel = \"pull\"\n")
	b.WriteString(")\n")

	b.WriteString("\nconst (\n")
	for i, k := range kinds {
		if i > 0 {
			b.WriteString("\n")
		}
		plural := "facts"
		if len(k.Facts) == 1 {
			plural = "fact"
		}
		fmt.Fprintf(&b, "\t// %s is the subject kind %s, keyed by %d declared %s.\n",
			k.GoName(), k.Display(), len(k.Facts), plural)
		fmt.Fprintf(&b, "\t%s SubjectKind = %q\n", k.GoName(), k.Display())
	}
	b.WriteString(")\n")

	b.WriteString("\n")
	b.WriteString(wrapComment("", `SubjectKinds is every derived subject kind, in the order the first fact keyed by it is declared. It is a slice rather than a map so that a consumer walking it — one traversal per kind, one table row per kind — produces the same order on every run.`))
	b.WriteString("var SubjectKinds = []SubjectKindInfo{\n")
	for _, k := range kinds {
		model := "TraversalPull"
		if k.Traversal() == "push" {
			model = "TraversalPush"
		}
		fmt.Fprintf(&b, "\t{Kind: %s, Coordinates: []string{%s}, Traversal: %s},\n",
			k.GoName(), quoteList(k.Coordinates), model)
	}
	b.WriteString("}\n")

	b.WriteString("\n")
	b.WriteString(wrapComment("", `SubjectKindInfo is one derived subject kind together with what a traversal needs in order to enumerate it: the coordinates, outermost first, and the model by which instances are reached.`))
	b.WriteString("type SubjectKindInfo struct {\n")
	b.WriteString("\tKind        SubjectKind\n")
	b.WriteString("\tCoordinates []string\n")
	b.WriteString("\tTraversal   TraversalModel\n")
	b.WriteString("}\n")

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		return nil, fmt.Errorf("the generated subject-kind set is not valid Go: %w", err)
	}
	return out, nil
}

// hostPowerCell renders one stage's host-power declaration for the placement
// table.
//
// The empty declaration prints as a word rather than as a dash. A dash is what
// the table uses for a cell with nothing to say, and this cell always has
// something to say: the stage asserted that its production reaches for nothing,
// and generation would have refused it had it omitted the declaration instead.
func hostPowerCell(powers []hostPower) string {
	if len(powers) == 0 {
		return "none"
	}
	parts := make([]string, 0, len(powers))
	for _, p := range powers {
		parts = append(parts, "`"+string(p)+"`")
	}
	return strings.Join(parts, ", ")
}

func quoteList(ss []string) string {
	parts := make([]string, 0, len(ss))
	for _, s := range ss {
		parts = append(parts, fmt.Sprintf("%q", s))
	}
	return strings.Join(parts, ", ")
}

// emitSubjectKindsRegion renders the subject-kind set for the generated region
// of the framework's engineering-standards page.
//
// It is a narrower projection than the placement table's kind section on
// purpose. The page it lands in explains what a kind IS — coordinates nest but
// kinds do not — so the region carries the set, its coordinate nesting and its
// traversal, and points at the placement table for the per-fact view rather than
// restating it. Both projections come from this one derivation, so they cannot
// disagree; what would be a second copy is the derivation, not the presentation.
//
// The Go constant name is carried because the page's reader is a contributor who
// will go looking for the type, and it is the one field that lets them cross from
// the prose to the generated source without guessing at the capitalisation.
func emitSubjectKindsRegion(_ chain, kinds []kind, _ []tupleShare) ([]byte, error) {
	var b strings.Builder
	b.WriteString("*Generated from the fact registry at\n")
	b.WriteString("`aggrega-cli/internal/compiler/constraint/factgen/registry.go`. Do not hand-edit\n")
	b.WriteString("this region — the workspace build gates it for drift and prints the command that\n")
	b.WriteString("refreshes it.*\n\n")
	b.WriteString("A kind exists if and only if some declared fact is keyed by it, so this set is a\n")
	b.WriteString("consequence of the fact declarations rather than a list kept in step with them.\n")
	b.WriteString("Coordinates are ordered outermost first, so a check declaring a kind runs once\n")
	b.WriteString("per innermost coordinate within each outer one. Traversal is derived from the\n")
	b.WriteString("outermost coordinate: a document-rooted kind is push, because no point in the\n")
	b.WriteString("compilation holds a materialised document set to walk.\n\n")
	b.WriteString("| Kind | Coordinates | Traversal | Go constant | Keyed facts |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for _, k := range kinds {
		coords := make([]string, 0, len(k.Coordinates))
		for _, c := range k.Coordinates {
			coords = append(coords, "`"+c+"`")
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s | `%s` | %d |\n",
			k.Display(), strings.Join(coords, " › "), k.Traversal(), k.GoName(), len(k.Facts))
	}
	// The generated placement table is named rather than linked. This prose is a
	// string literal in a Go file, which is a user-visible surface, so it carries
	// no path into a private documentation tree — the page's own curated prose,
	// which may cite such a path freely, already points the reader at it.
	fmt.Fprintf(&b, "\n%d kinds, keyed by %d declared facts. Which facts key which kind, and at\n",
		len(kinds), len(facts))
	b.WriteString("which stage each is complete, is carried by the generated placement table\n")
	b.WriteString("named at the top of this page.\n")

	return []byte(strings.TrimRight(b.String(), "\n")), nil
}

// emitPlacementTable renders the reviewable placement table.
func emitPlacementTable(c chain, kinds []kind, shares []tupleShare) ([]byte, error) {
	var b strings.Builder
	b.WriteString("<!-- Code generated by internal/compiler/constraint/factgen from the fact\n")
	b.WriteString("registry. DO NOT EDIT. This file is committed outside the generator's own\n")
	b.WriteString("module, so no generate directive names it: regenerate by running that\n")
	b.WriteString("generator with this file's path as its argument. The workspace build gates\n")
	b.WriteString("this file for drift and prints the exact command when it is stale. -->\n\n")
	b.WriteString("# Constraint fact placement\n\n")
	b.WriteString("Generated from the fact registry at\n")
	b.WriteString("`aggrega-cli/internal/compiler/constraint/factgen/registry.go`. This table is\n")
	b.WriteString("authoritative for placement: a check's stage is the stage of the view it\n")
	b.WriteString("declares, and a view's stage is fixed by which facts land on it.\n\n")
	b.WriteString("**Placement is not enforcement, and no table below says a rule is enforced.**\n")
	b.WriteString("A check's stage is where it would be invoked; whether anything invokes it is a\n")
	b.WriteString("separate question, answered for each declared check in the next section. Read\n")
	b.WriteString("that section before reading a stage row as a guard.\n\n")
	b.WriteString("The measured census this registry was declared from keeps the read-site\n")
	b.WriteString("counts and the near-duplicate reasoning a generated table cannot carry. For\n")
	b.WriteString("placement, this table supersedes it.\n\n")

	if err := writeInvocationSection(&b, c); err != nil {
		return nil, err
	}

	b.WriteString("## The view stages\n\n")
	b.WriteString("Stages nest by interface embedding, so their order is a compile-time fact. The\n")
	b.WriteString("chain is asserted linear at generation time: a stage extending nothing when\n")
	b.WriteString("another already does, or two stages extending the same stage, halts generation\n")
	b.WriteString("rather than emitting a chain with an unordered pair in it.\n\n")
	b.WriteString("The host powers are what that stage's own fact production reaches for outside\n")
	b.WriteString("the compiler's own computation. They describe the production and never a\n")
	b.WriteString("check: a check receives its view and its subject and nothing else, so every\n")
	b.WriteString("value it reads was already produced for it. A stage reaching for nothing\n")
	b.WriteString("declares that rather than omitting it, and an omission halts generation, so a\n")
	b.WriteString("cell reading `none` is an assertion and not a gap.\n\n")
	b.WriteString("| Stage | Contains | What is complete | Host powers | Facts |\n")
	b.WriteString("|---|---|---|---|---|\n")
	for i, s := range c.order {
		contains := "—"
		if i > 0 {
			contains = "`" + c.order[i-1].Name + "`"
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s | %s | %d |\n",
			s.Name, contains, s.Holds, hostPowerCell(s.HostPowers), len(c.facts[s.Name]))
	}
	fmt.Fprintf(&b, "\nTotal: **%d facts** over **%d stages**.\n\n", len(facts), len(c.order))

	b.WriteString("## Facts\n\n")
	b.WriteString("The source carrier is the pipeline product field the fact reads, named as a Go\n")
	b.WriteString("structure and field — or, where the product is carried as a function parameter\n")
	b.WriteString("rather than as a field, that single carrier. The subject key is what the fact\n")
	b.WriteString("is keyed by; it derives the subject-kind set and is deliberately distinct from\n")
	b.WriteString("the accessor's arguments, which may read a projection of a coordinate.\n\n")
	b.WriteString("| Fact | Accessor | Stage | Source carrier | Subject key | Result |\n")
	b.WriteString("|---|---|---|---|---|---|\n")
	for _, s := range c.order {
		for _, f := range c.facts[s.Name] {
			fmt.Fprintf(&b, "| `%s` | `%s(%s)` | `%s` | `%s` | `%s` | `%s` |\n",
				f.Name, accessorName(f.Name), paramList(f.Params), f.Stage,
				f.SourceField, kind{Coordinates: f.Subject}.Display(), f.Returns)
		}
	}
	b.WriteString("\n")

	b.WriteString("## Reported exceptions to the no-raw-document rule\n\n")
	var exceptions []factDecl
	for _, f := range facts {
		if f.ReportedException != "" {
			exceptions = append(exceptions, f)
		}
	}
	if len(exceptions) == 0 {
		b.WriteString("None. Every accessor's result is free of authored-entity types and of\n")
		b.WriteString("diagnostic shapes.\n\n")
	} else {
		b.WriteString("A fact listed here does not satisfy the rule that a view exposes named facts\n")
		b.WriteString("and never a raw document. It is reported rather than admitted silently: the\n")
		b.WriteString("guard names it, this table prints it, and its shape is open rather than\n")
		b.WriteString("settled.\n\n")
		for _, f := range exceptions {
			fmt.Fprintf(&b, "- `%s` (`%s`, keyed `%s`, returning `%s`) — %s.\n",
				f.Name, f.Stage, kind{Coordinates: f.Subject}.Display(), f.Returns, f.ReportedException)
		}
		b.WriteString("\n")
	}

	b.WriteString("## The derived subject-kind set\n\n")
	b.WriteString("A kind exists if and only if some fact is keyed by it, so the count is\n")
	b.WriteString("whatever the registry says. The traversal model is derived from the kind's\n")
	b.WriteString("outermost coordinate: a document-rooted kind is push, because no point in the\n")
	b.WriteString("compilation holds a materialised document set to walk.\n\n")
	b.WriteString("| Kind | Traversal | Keyed facts |\n")
	b.WriteString("|---|---|---|\n")
	for _, k := range kinds {
		quoted := make([]string, 0, len(k.Facts))
		for _, f := range k.Facts {
			quoted = append(quoted, "`"+f+"`")
		}
		fmt.Fprintf(&b, "| `%s` | %s | %s |\n", k.Display(), k.Traversal(), strings.Join(quoted, ", "))
	}
	fmt.Fprintf(&b, "\nTotal: **%d kinds**.\n\n", len(kinds))

	b.WriteString("## Facts sharing a (stage, source carrier, subject) tuple\n\n")
	b.WriteString("Two facts sharing all three read one carrier at one point of the compilation\n")
	b.WriteString("and answer one subject. **A share is not proof of duplication.** Same-name\n")
	b.WriteString("duplication is closed by two mechanisms rather than one: the language rejects\n")
	b.WriteString("two declarations of a name at one stage, or at two stages with differing\n")
	b.WriteString("signatures, while the case it admits — two stages and an identical signature,\n")
	b.WriteString("which a method set may carry through embedding — is refused by the generator.\n")
	b.WriteString("Same semantics under two different names is not closed and there is no\n")
	b.WriteString("mechanism for it — this list is the mitigation, and it turns an invisible risk\n")
	b.WriteString("into a reviewable one. It is also bounded: it says\n")
	b.WriteString("nothing about one rule restated at two stages over two carriers, which is a\n")
	b.WriteString("shape it structurally cannot see.\n\n")
	if len(shares) == 0 {
		b.WriteString("No two declared facts share a tuple.\n")
	} else {
		b.WriteString("| Stage | Source carrier | Subject | Facts |\n")
		b.WriteString("|---|---|---|---|\n")
		for _, sh := range shares {
			quoted := make([]string, 0, len(sh.Facts))
			for _, f := range sh.Facts {
				quoted = append(quoted, "`"+f+"`")
			}
			fmt.Fprintf(&b, "| `%s` | `%s` | `%s` | %s |\n",
				sh.Stage, sh.SourceField, sh.Subject, strings.Join(quoted, ", "))
		}
	}

	return []byte(b.String()), nil
}

// wrapComment renders prose as a Go comment block at a fixed width, so that
// regenerating unchanged prose reproduces byte-identical output. Paragraphs are
// separated in the input by a blank line and in the output by a bare comment
// marker.
func wrapComment(indent, prose string) string {
	const width = 72
	var b bytes.Buffer
	for i, para := range strings.Split(prose, "\n\n") {
		if i > 0 {
			b.WriteString(indent + "//\n")
		}
		line := ""
		for _, word := range strings.Fields(para) {
			switch {
			case line == "":
				line = word
			case len(line)+1+len(word) <= width:
				line += " " + word
			default:
				b.WriteString(indent + "// " + line + "\n")
				line = word
			}
		}
		if line != "" {
			b.WriteString(indent + "// " + line + "\n")
		}
	}
	return b.String()
}
